suppressPackageStartupMessages(library(tidyverse))
r<-'.';out<-commandArgs(TRUE)[1]
p<-read_csv(file.path(r,'data_panels/2010_2019_did_panel_with_seer.csv'),show_col_types=FALSE,col_select=c(tract_id,year,rac_total,wac_total,seer_total_population,first_pis_year,acs2010_median_hh_income))
pa<-read_csv(file.path(out,'matched_pairs.csv'),show_col_types=FALSE)
d<-pa%>%select(group,match_id,tract_id,cohort,treated_cohort)%>%inner_join(p,by='tract_id',relationship='many-to-many')%>%mutate(ratio=rac_total/seer_total_population,pre=year<cohort)
write_csv(d%>%filter(seer_total_population<100|ratio>2),file.path(out,'small_population_or_high_ratio_rows.csv'))
a<-d%>%group_by(group,match_id,tract_id,cohort,treated_cohort)%>%summarise(min_pop=min(seer_total_population,na.rm=TRUE),min_pre_pop=min(seer_total_population[pre],na.rm=TRUE),max_ratio=max(ratio,na.rm=TRUE),max_pre_ratio=max(ratio[pre],na.rm=TRUE),.groups='drop')
write_csv(a,file.path(out,'tract_pair_audit.csv'))
write_csv(a%>%group_by(group,treated_cohort)%>%summarise(n=n(),pre_pop_lt10=sum(min_pre_pop<10),pre_pop_lt50=sum(min_pre_pop<50),pre_pop_lt100=sum(min_pre_pop<100),pre_pop_lt500=sum(min_pre_pop<500),pre_ratio_gt1=sum(max_pre_ratio>1),pre_ratio_gt2=sum(max_pre_ratio>2),.groups='drop'),file.path(out,'small_population_summary.csv'))
b<-d%>%filter(year==cohort-1)%>%select(group,match_id,cohort,treated_cohort,tract_id,seer_total_population,rac_total,wac_total,ratio)%>%pivot_wider(names_from=treated_cohort,values_from=c(tract_id,seer_total_population,rac_total,wac_total,ratio))%>%mutate(pop_factor=pmax(seer_total_population_1,seer_total_population_0)/pmin(seer_total_population_1,seer_total_population_0),rac_factor=pmax(rac_total_1,1,rac_total_0)/pmax(pmin(rac_total_1,rac_total_0),1),wac_factor=pmax(wac_total_1,1,wac_total_0)/pmax(pmin(wac_total_1,wac_total_0),1),ratio_gap=abs(ratio_1-ratio_0))
write_csv(b%>%arrange(desc(pop_factor)),file.path(out,'pair_scale_audit.csv'))
write_csv(b%>%group_by(group)%>%summarise(n=n(),pop_gt2=sum(pop_factor>2),pop_gt3=sum(pop_factor>3),pop_gt5=sum(pop_factor>5),pop_gt10=sum(pop_factor>10),rac_gt2=sum(rac_factor>2),rac_gt5=sum(rac_factor>5),wac_gt5=sum(wac_factor>5),wac_gt10=sum(wac_factor>10),ratio_gap_gt_point2=sum(ratio_gap>.2),.groups='drop'),file.path(out,'pair_scale_summary.csv'))

stopifnot(all(a$min_pre_pop>=100),all(!(a$tract_id %% 1000000>=980000 & a$tract_id %% 1000000<990000)),all(b$pop_factor<=3+1e-10),all(b$rac_factor<=5+1e-10),all(b$wac_factor<=5+1e-10))
writeLines('PASS: all matched roles meet pretreatment population and special-use eligibility; all baseline population ratios<=3 and RAC/WAC ratios<=5.',file.path(out,'GUARD_VALIDATION.txt'))
